		/** 
		 * Tests creating a new Creditor.
		 */
		public void testCreate() throws Throwable {
			LOGGER.info( "\n======== CREATE ======== ");
			LOGGER.info( "-- Attempting to create a Creditor");

			StringBuilder msg = new StringBuilder( "-- Failed to create a Creditor" );

			try {            
				Creditor entity = CreditorService.getCreditorInstance().createCreditor( generateNewEntity() );
				thePrimaryKey = entity.getCreditorId();
				LOGGER.info( "-- Successfully created a Creditor with primary key" + thePrimaryKey );
			}
			catch (Exception e) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests reading a Creditor. 
		 */
		public Creditor testRead() throws Throwable {
			LOGGER.info( "\n======== READ ======== ");
			LOGGER.info( "-- Reading a previously created Creditor" );

			Creditor entity = null;
			StringBuilder msg = new StringBuilder( "-- Failed to read Creditor with primary key" );
			msg.append( thePrimaryKey );
			
			CreditorFetchOneSummary fetchOneSummary = new CreditorFetchOneSummary( thePrimaryKey );

			try {
				entity = CreditorService.getCreditorInstance().getCreditor( fetchOneSummary );

				assertNotNull( entity,msg.toString() );

				LOGGER.info( "-- Successfully found Creditor " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
			
			return entity;
		}

		/** 
		 * Tests updating a Creditor.
		 */
		public void testUpdate() throws Throwable {
			LOGGER.info( "\n======== UPDATE ======== ");
			LOGGER.info( "-- Attempting to update a Creditor." );

			StringBuilder msg = new StringBuilder( "Failed to update a Creditor : " );        
			Creditor entity = null;

			try {            
				entity = testRead();

				assertNotNull( entity, msg.toString() );

				LOGGER.info( "-- Now updating the created Creditor." );

				// for use later on...
				thePrimaryKey = entity.getCreditorId();

				CreditorService proxy = CreditorService.getCreditorInstance();            
				proxy.updateCreditor( entity );   

				LOGGER.info( "-- Successfully saved Creditor - " + entity.toString() );
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : primarykey = " + thePrimaryKey + " : entity-" +  entity + " : " + e );

				throw e;
			}
		}

		/** 
		 * Tests deleting a Creditor.
		 */
		public void testDelete() throws Throwable {
			LOGGER.info( "\n======== DELETE ======== ");
			LOGGER.info( "-- Deleting a previously created Creditor." );

			try{
			    Creditor entity = testRead(); 
				CreditorService.getCreditorInstance().delete( entity );

				LOGGER.info( "-- Successfully deleted Creditor with primary key " + thePrimaryKey );            
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( "-- Failed to delete Creditor with primary key " + thePrimaryKey );

				throw e;
			}
		}

		/**
		 * Tests getting all Creditors.
		 */
		public void testGetAll() throws Throwable {    
			LOGGER.info( "======== GETALL ======== ");
			LOGGER.info( "-- Retrieving Collection of Creditors:" );

			StringBuilder msg = new StringBuilder( "-- Failed to get all Creditor : " );        
			List<Creditor> collection  = null;

			try {
				// call the static get method on the CreditorService
				collection = CreditorService.getCreditorInstance().getAllCreditor();

				if ( collection == null || collection.size() == 0 ) {
					LOGGER.warning( unexpectedErrorMsg );
					LOGGER.warning( msg.toString() + " Empty collection returned."  );
				}
				else {
					// Now print out the values
					Creditor entity = null;            
					Iterator<Creditor> iter = collection.iterator();
					int index = 1;

					while( iter.hasNext() ) {
						// Retrieve the entity   
						entity = iter.next();

						assertNotNull( entity,"-- null entity in Collection." );
						assertNotNull( entity.getCreditorId(), "-- entity in Collection has a null primary key" );        

						LOGGER.info( " - " + String.valueOf(index) + ". " + entity.toString() );
						index++;
					}
				}
			}
			catch ( Throwable e ) {
				LOGGER.warning( unexpectedErrorMsg );
				LOGGER.warning( msg.toString() + " : " + e );

				throw e;
			}
		}

